export interface Oklch {
  /** Perceptual lightness, 0 to 1. */
  l: number;
  /** Chroma. */
  c: number;
  /** Hue in degrees. */
  h: number;
}

export interface Color {
  /** The gamut this rendition resolved against. */
  gamut: string;
  /** Channel values as `#rrggbb`, in that gamut's encoding. */
  hex: string;
  oklch: Oklch;
  /** Ready to drop into CSS. */
  css: string;
  /** Fraction of the gamut boundary actually reached. */
  relativeChroma: number;
  /** Fraction the spec asked for, before the gamut had a say. */
  requestedRelativeChroma: number;
  /** Chroma remaining between this color and the boundary. */
  chromaHeadroom: number;
}

export interface Step {
  role: string;
  index: number;
  /** One entry per gamut, primary first. */
  renditions: Color[];
}

export interface Family {
  baseHue: number;
  steps: Step[];
}

export interface ModePalette {
  families: Record<FamilyName, Family>;
  /** Semantic name to the `family-role` stem it points at. */
  semantic: Record<SemanticName, string>;
  chart: Step[];
}

export interface Palette {
  prefix: string;
  gamuts: string[];
  roles: RoleName[];
  /** The dense neutral ramp, shared by every theme and mode. */
  grayRamp: Step[];
  themes: Record<ThemeName, Record<Mode, ModePalette>>;
}

export declare const palette: Palette;
export default palette;
